from fractions import Fraction
import math

def calculate_R_Kn(n):
    if n < 4:
        return Fraction(0)

    # f(K_n) = C(n, 3) = n(n-1)(n-2)/6
    # g(K_n) = C(n, 4) = n(n-1)(n-2)(n-3)/24

    # Using the simplified ratio formula: R(K_n) = 3 * (n-3)^3 / (32 * n * (n-1) * (n-2))

    numerator = 3 * (n - 3)**3
    denominator = 32 * n * (n - 1) * (n - 2)

    return Fraction(numerator, denominator)

results = {}
max_ratio = Fraction(0)
max_n = 0

for n in range(3, 16):
    ratio = calculate_R_Kn(n)
    results[n] = ratio

    if ratio > max_ratio:
        max_ratio = ratio
        max_n = n

print("Calculations for n=3 to n=15:")
for n, ratio in results.items():
    print(f"R(K_{n}) = {ratio}")

print(f"\nMaximum Ratio found: {max_ratio} at n={max_n}")
